const $=s=>document.querySelector(s);$('#compare').addEventListener('input',e=>$('.compare').style.setProperty('--pos',e.target.value+'%'));const products=$('.products');$('#next').onclick=()=>products.scrollBy({left:products.clientWidth*.8,behavior:'smooth'});$('#prev').onclick=()=>products.scrollBy({left:-products.clientWidth*.8,behavior:'smooth'});document.querySelectorAll('.product').forEach(p=>p.onclick=()=>{$('#producttitle').textContent=p.dataset.title;$('#model').innerHTML=p.dataset.kind==='mirror'?'<div class="mirror"></div>':'<div class="faucet"><i></i></div>';$('#rotate').value=0;$('#degrees').textContent='0°';$('#productmodal').showModal()});$('#rotate').oninput=e=>{$('#model>div').style.transform=`rotateY(${e.target.value}deg)`;$('#degrees').textContent=e.target.value+'°'};document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d&& (e.offsetX<0||e.offsetY<0||e.offsetX>d.clientWidth||e.offsetY>d.clientHeight))d.close()}));$('#book').onclick=()=>$('#contact').showModal();$('#contactform').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);$('#contactresult').textContent=`Thank you, ${f.get('name')}. Your consultation summary is ready for ${f.get('email')}. This is a local preview; no enquiry has been sent.`;const blob=new Blob([`THE BATHSTORE — Consultation enquiry\nName: ${f.get('name')}\nEmail: ${f.get('email')}\nVision: ${f.get('vision')}`],{type:'text/plain'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='bathstore-consultation.txt';a.textContent='Download your enquiry summary ↗';$('#contactresult').append(document.createElement('br'),a)};$('#approve').onclick=()=>{$('#approval').textContent='Concept estimate selected. A personalised scope and final quotation are required before approval.';$('#contact').showModal()};const sections=['consultation','vision','collection','blueprint'];const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('.steps a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}})},{rootMargin:'-20% 0px -45% 0px'});sections.forEach(id=>observer.observe(document.getElementById(id)));
